        // resolve against the page's own address. (They're lazy, so only the ones near the screen load.)
        root.querySelectorAll('img.kp-aw-shot[data-src]').forEach((img) => { img.src = new URL(img.dataset.src, location.href).href })

        // Flip cards: one card is turned over at a time. The hidden face is inert, so Tab and clicks only reach the
        // side that's showing.
        function flip(card, on) {
            if (on) root.querySelectorAll('.kp-aw-card.is-flipped').forEach((c) => c !== card && flip(c, false))
            card.classList.toggle('is-flipped', on)
            card.querySelector('.kp-aw-front').inert = on
            card.querySelector('.kp-aw-back').inert = !on
            card.querySelector('.kp-aw-hit').setAttribute('aria-expanded', String(on))
        }
        // What Tab and the arrow keys land on in each slide: the flip button, the close button while the card is
        // over, or the card link itself (the reel).
        function primary(slide) {
            const card = slide.querySelector('.kp-aw-card')
            if (!card.hasAttribute('data-flip')) return card
            return card.querySelector(card.classList.contains('is-flipped') ? '.kp-aw-close' : '.kp-aw-hit')
        }

        // Keyboard: Tab walks the cards and brings each one into view; arrows step, Home/End jump, Esc turns a card back.
        function focusCard(i) {
            const list = slides()
            i = Math.max(0, Math.min(list.length - 1, i))
            go(i)
            primary(list[i]).focus({ preventScroll: true })
        }
        root.addEventListener('keydown', (e) => {
            const list = slides()
            const i = list.findIndex((s) => s.contains(document.activeElement))
            const onCard = i > -1
            if (e.key === 'ArrowRight') { e.preventDefault(); onCard ? focusCard(i + 1) : go(current() + 1) }
            else if (e.key === 'ArrowLeft') { e.preventDefault(); onCard ? focusCard(i - 1) : go(current() - 1) }
            else if (e.key === 'Home' && onCard) { e.preventDefault(); focusCard(0) }
            else if (e.key === 'End' && onCard) { e.preventDefault(); focusCard(list.length - 1) }
        }, on)
        el.addEventListener('focusin', (e) => {
            // Keyboard focus only: pressing a flip button with the mouse focuses it too, and that mustn't move the row.
            if (!e.target.matches(':focus-visible')) return
            const slide = e.target.closest('.kp-aw-slide')
            if (!slide) return
            const r = slide.getBoundingClientRect()
            const box = el.getBoundingClientRect()
            const left = box.left + o.left
            const right = box.right - o.right
            if (r.left < left - 1 || r.right > right + 1) go(slides().indexOf(slide))
        }, on)

        // Clicks. Swiper swallows the click itself when it ends a drag, so none of this fires mid-swipe. Focus follows
        // the card over only for Enter/Space (click detail 0): Swiper won't start a touch drag on a focused button, so
        // moving focus after a tap would freeze the row on phones.
        el.addEventListener('click', (e) => {
            const kb = e.detail === 0
            const hit = e.target.closest('.kp-aw-hit')
            if (hit) {
                const card = hit.closest('.kp-aw-card')
                flip(card, true)
                if (kb) card.querySelector('.kp-aw-close').focus({ preventScroll: true })
                return
            }
            // Anywhere on the back turns the card over again.
            const back = e.target.closest('.kp-aw-back')
            if (back && !e.target.closest('a')) {
                const card = back.closest('.kp-aw-card')
                flip(card, false)
                if (kb) card.querySelector('.kp-aw-hit').focus({ preventScroll: true })
            }
        }, on)
        // Esc turns an open card back, wherever focus is.
        document.addEventListener('keydown', (e) => {
            if (e.key !== 'Escape') return
            const open = root.querySelector('.kp-aw-card.is-flipped')
            if (!open) return
            const inside = open.contains(document.activeElement)
            flip(open, false)
            if (inside) open.querySelector('.kp-aw-hit').focus({ preventScroll: true })
        }, on)

        // Reel card: hand the click to the hidden round button, which the site's script already wires to the reel popup.
        el.addEventListener('click', (e) => {
            const card = e.target.closest('.kp-aw-card[data-kind="reel"]')
            if (!card) return
            e.preventDefault()
            const btn = page.querySelector('.home-abt-btn-video[data-popup="showreel"]')
            if (btn) btn.click()
        }, on)
        // Its loop loads and plays only while the card is on screen, and never for reduced motion or Save-Data
        // (they keep the still). The path resolves against the page rather than the prototype's <base>, and it rides
        // in data-kp-src because the site's lazy-video script claims every video[data-src].
        const vid = root.querySelector('.kp-aw-reel-vid')
